@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--ink:#f6f1ff;--muted:#a19bb4;--gold:#ffc95e;--pink:#ff4d91;--panel:#171327}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#100d20;color:var(--ink);font-family:Manrope,system-ui,sans-serif}body{display:grid;place-items:center;padding:20px;background:radial-gradient(ellipse at 50% 0%,#282044 0,#100d20 66%)}button{font:inherit;color:inherit}.game-shell{width:min(1200px,100%);margin:auto}.topbar{height:56px;display:flex;align-items:center;justify-content:space-between;padding:0 6px 12px}.brand{display:flex;gap:10px;align-items:center;text-decoration:none;color:var(--ink);font:800 16px 'Barlow Condensed',sans-serif;letter-spacing:1.6px}.brand small{display:block;color:#a49bb7;font:500 8px 'DM Mono',monospace;letter-spacing:2px;margin-top:1px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid #55466c;color:var(--gold);font:900 23px 'Barlow Condensed',sans-serif;transform:skew(-8deg)}.top-note{font:500 10px 'DM Mono',monospace;letter-spacing:2px;color:#c5bfd0}.live-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#77f0b0;margin-right:8px;box-shadow:0 0 10px #77f0b0}.sound-button{background:#211b31;border:1px solid #373047;border-radius:8px;padding:8px 11px;color:var(--gold);font-weight:800;cursor:pointer}.sound-button span{font:9px 'DM Mono',monospace;letter-spacing:1px;color:#aaa2b7;margin-left:4px}.stage-wrap{position:relative;width:100%;aspect-ratio:16/9;border:1px solid #413650;border-radius:14px;overflow:hidden;background:#171329;box-shadow:0 26px 90px #070610aa,0 0 0 5px #171327}.stage-wrap:after{content:"";position:absolute;inset:0;pointer-events:none;border-radius:14px;box-shadow:inset 0 0 0 1px #ffffff12,inset 0 0 70px #08061155}canvas{display:block;width:100%;height:100%;touch-action:none}.help-row{height:48px;display:flex;align-items:center;justify-content:space-between;color:#a9a2b7;font:9px 'DM Mono',monospace;letter-spacing:1px;padding:8px 8px 0}.keycap{display:inline-grid;place-items:center;min-width:19px;height:19px;padding:0 4px;margin-right:3px;border:1px solid #50465e;border-bottom-width:2px;border-radius:4px;background:#211b31;color:#f7f1ff;font:10px 'DM Mono',monospace}.divider{padding:0 8px;color:#615970}.footer-right{color:#777084}.footer-right strong{color:var(--gold);font-weight:500}.mobile-controls{display:none;position:absolute;z-index:2;bottom:9px;left:0;right:0;justify-content:space-between;align-items:flex-end;padding:0 12px;pointer-events:none}.touch-group{display:flex;gap:6px;pointer-events:auto}.touch-group button{height:48px;min-width:45px;padding:0 10px;border:1px solid #fff4;border-radius:13px;background:#1a1539c9;color:#fff;font-weight:800;font-size:15px;touch-action:none;user-select:none;backdrop-filter:blur(8px)}.attacks button{font:700 9px 'DM Mono',monospace;letter-spacing:.5px;color:#ffdb8d}.attacks button:last-child{color:#ff86ac}.touch-group button:active{background:#7443a9}
@media(max-width:700px){body{padding:8px}.topbar{height:44px;padding-bottom:7px}.top-note{font-size:8px;letter-spacing:1px}.stage-wrap{border-radius:8px;box-shadow:0 8px 24px #070610aa}.stage-wrap:after{border-radius:8px}.help-row{display:none}.mobile-controls{display:flex}.touch-group{gap:4px}.touch-group button{height:40px;min-width:39px;border-radius:10px;padding:0 8px}.attacks button{font-size:8px}.brand{font-size:14px}.brand-mark{width:29px;height:29px;font-size:20px}}
@media(max-width:390px){.top-note{display:none}.touch-group button{height:36px;min-width:34px;padding:0 6px}.attacks button{font-size:7px}}

(()=>{
'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),W=960,H=540,ground=438;
const fighters=[{name:'MICHAEL JACKSON',short:'THE MOONWALKER',color:'#e94155',accent:'#f2c955',skin:'#9a684f',hair:'#17131b',special:'MOONWALKER RUSH',tag:'THE KING OF POP'}, {name:'LEBRON JAMES',short:'THE KING',color:'#6e4ee7',accent:'#ffc84f',skin:'#8e5c40',hair:'#17131b',special:'CROWN BREAKER',tag:'THE COURT LEGEND'}];
let selected=0,mode=1,state='menu',paused=false,round=1,timer=60,roundTimer=0,screenTime=0,last=0,shake=0,flash=0,soundOn=true,audioCtx=null;
const keys=new Set(),touchKeys=new Set(),particles=[],texts=[];let fightersLive=[];
const keyMap={a:'a',d:'d',w:'w',s:'s',f:'f',g:'g',h:'h',ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down',j:'j',k:'k',l:'l'};
function makeFighter(kind,x,player){return {kind,x,y:ground,vx:0,vy:0,face:player===1?1:-1,health:100,player,attack:null,attackCooldown:0,stun:0,block:false,jumping:false,walk:0,flash:0,energy:0,aiClock:0,hitOnce:false};}
function startGame(){round=1;initRound();state='fight';paused=false;screenTime=0;}
function initRound(){fightersLive=[makeFighter(selected,260,1),makeFighter(mode===2?1-selected:1-selected,700,2)];fightersLive[0].face=1;fightersLive[1].face=-1;timer=60;roundTimer=0;particles.length=0;texts.length=0;}
function finishRound(){if(state!=='fight')return;state='over';roundTimer=0;const [a,b]=fightersLive;let winner=a.health===b.health?'DRAW':a.health>b.health?'P1':'P2';window.winner=winner;sound(winner==='DRAW'?180:440,.22);}
function sound(freq=260,duration=.08){if(!soundOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='triangle';o.frequency.value=freq;g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
function pressed(k){return keys.has(k)||touchKeys.has(k)}
function input(player){if(player===1)return {left:pressed('a'),right:pressed('d'),jump:pressed('w'),block:pressed('s'),light:pressed('f'),heavy:pressed('g'),special:pressed('h')};return {left:pressed('left'),right:pressed('right'),jump:pressed('up'),block:pressed('down'),light:pressed('j'),heavy:pressed('k'),special:pressed('l')}}
function cpuInput(f,other,dt){const d=other.x-f.x,dist=Math.abs(d);f.face=d>=0?1:-1;f.aiClock-=dt;const q={left:false,right:false,jump:false,block:false,light:false,heavy:false,special:false};if(mode===2)return input(2);if(dist>112){if(d>0)q.right=true;else q.left=true;if(dist>230&&Math.random()<.008)q.jump=true;}else{if(other.attack&&Math.random()<.07)q.block=true;if(f.aiClock<=0){f.aiClock=.34+Math.random()*.55;let r=Math.random();if(f.energy>=45&&dist<190&&r<.2)q.special=true;else if(r<.55)q.light=true;else if(r<.84)q.heavy=true;else q.block=true;}else if(f.aiClock>.16&&f.attackCooldown===0&&Math.random()<.035)q.light=true;}return q;}
function initiateAttack(f,type){if(f.attackCooldown>0||f.stun>0||f.attack)return;let spec={light:{startup:7,active:7,recovery:17,damage:7,range:82,cost:0},heavy:{startup:15,active:9,recovery:25,damage:13,range:102,cost:0},special:{startup:18,active:12,recovery:35,damage:19,range:185,cost:45}}[type];if(type==='special'&&f.energy<spec.cost)return;if(type==='special')f.energy-=spec.cost;f.attack={type,t:0,...spec,hit:false};f.attackCooldown=spec.startup+spec.active+spec.recovery;f.hitOnce=false;sound(type==='special'?580:type==='heavy'?340:230,.07);}
function controlsFor(f,q,other,dt){f.block=q.block&&f.y>=ground-1&&!f.attack;if(f.attackCooldown>0)f.attackCooldown=Math.max(0,f.attackCooldown-dt*60);if(f.stun>0)f.stun=Math.max(0,f.stun-dt*60);if(f.flash>0)f.flash-=dt*60;
 if(!f.attack&&!f.stun){let dir=(q.right?1:0)-(q.left?1:0);if(!f.block){f.vx=dir*235;if(dir)f.walk+=dt*9;else f.walk*=.75;}else f.vx*=.7;if(q.jump&&f.y>=ground-1){f.vy=-480;f.jumping=true;sound(300,.06)}if(q.light)initiateAttack(f,'light');else if(q.heavy)initiateAttack(f,'heavy');else if(q.special)initiateAttack(f,'special');}
 if(f.attack){f.attack.t+=dt*60;if(f.attack.t>=f.attack.startup&&f.attack.t<f.attack.startup+f.attack.active&&!f.attack.hit){let reach=f.attack.range;const close=Math.abs(other.x-f.x)<reach+23,front=(other.x-f.x)*f.face>0;if(close&&front&&Math.abs(other.y-f.y)<92){let blocked=other.block&&other.face===-f.face;let dmg=blocked?Math.ceil(f.attack.damage*.18):f.attack.damage;other.health=Math.max(0,other.health-dmg);other.energy=Math.min(100,other.energy+(blocked?7:13));f.energy=Math.min(100,f.energy+10);other.stun=blocked?5:(f.attack.type==='heavy'?15:10);other.vx=blocked?f.face*70:f.face*(f.attack.type==='special'?320:210);other.flash=8;f.attack.hit=true;f.hitOnce=true;shake=blocked?4:9;flash=blocked?.08:.16;burst(other.x,other.y-60,blocked?'#ffc95e':fighters[f.kind].accent,blocked?8:17);floatingText(other.x,other.y-114,blocked?'GUARD!':`-${dmg}`,blocked?'#ffe39a':'#fff');sound(blocked?180:f.attack.type==='special'?120:90,.11);}
 }if(f.attack.t>=f.attack.startup+f.attack.active+f.attack.recovery)f.attack=null;}
 f.vy+=1250*dt;f.y+=f.vy*dt;if(f.y>=ground){f.y=ground;f.vy=0;f.jumping=false;}f.x+=f.vx*dt;f.x=Math.max(70,Math.min(W-70,f.x));if(!f.attack&&f.stun===0)f.vx*=Math.pow(.001,dt);}
function burst(x,y,color,n){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=70+Math.random()*260;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+Math.random()*.5,max:.75,color,r:2+Math.random()*4});}}
function floatingText(x,y,text,color){texts.push({x,y,text,color,life:.7});}
function step(dt){screenTime+=dt;if(state==='fight'&&!paused){roundTimer+=dt;timer=Math.max(0,60-Math.floor(roundTimer));const [a,b]=fightersLive;if(a&&b){a.face=b.x>=a.x?1:-1;b.face=a.x>=b.x?1:-1;const qa=input(1),qb=mode===2?input(2):cpuInput(b,a,dt);controlsFor(a,qa,b,dt);controlsFor(b,qb,a,dt);if(Math.abs(a.x-b.x)<53){let push=(53-Math.abs(a.x-b.x))/2;a.x-=Math.sign(b.x-a.x)*push;b.x+=Math.sign(b.x-a.x)*push;}if(a.health<=0||b.health<=0||timer<=0)finishRound();}}
 for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=420*dt;if(p.life<=0)particles.splice(i,1)}for(let i=texts.length-1;i>=0;i--){texts[i].life-=dt;texts[i].y-=36*dt;if(texts[i].life<=0)texts.splice(i,1)}shake=Math.max(0,shake-dt*30);flash=Math.max(0,flash-dt);}
function draw(){ctx.save();if(shake){ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake)}drawArena();if(state==='fight'||state==='over'){drawHud();fightersLive.forEach(drawFighter);drawEffects();if(state==='fight'&&roundTimer<2.1)drawRoundIntro();if(paused)drawPause();if(state==='over')drawResult();}else drawMenu();ctx.restore();}
function drawArena(){let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#1c1732');g.addColorStop(.63,'#302044');g.addColorStop(1,'#11101f');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // Spotlight beams
 for(let i=0;i<5;i++){ctx.save();ctx.globalAlpha=.07;ctx.fillStyle=i%2?'#f5c46b':'#c384ff';ctx.beginPath();ctx.moveTo(115+i*185,0);ctx.lineTo(35+i*185,ground);ctx.lineTo(245+i*185,ground);ctx.closePath();ctx.fill();ctx.restore();}
 // crowd
 ctx.fillStyle='#191327';ctx.fillRect(0,247,W,166);for(let i=0;i<90;i++){let x=(i*67)%W,y=266+(i*29%132);ctx.fillStyle=['#594968','#372c4a','#806177','#2c2841'][i%4];ctx.beginPath();ctx.arc(x,y,5+(i%3),0,Math.PI*2);ctx.fill();ctx.fillRect(x-7,y+6,14,24+(i%14));}
 // led boards
 ctx.fillStyle='#10101b';ctx.fillRect(0,227,W,29);ctx.fillStyle='#bc8b40';ctx.fillRect(0,227,W,2);ctx.fillRect(0,253,W,2);ctx.font='700 11px "DM Mono", monospace';ctx.fillStyle='#ffd778';ctx.textAlign='center';ctx.fillText('✦  THE ICON ARENA  ✦     •     ONE NIGHT ONLY     •     THE ICON ARENA  ✦',480,246);
 // floor
 let floor=ctx.createLinearGradient(0,ground,0,H);floor.addColorStop(0,'#51405f');floor.addColorStop(1,'#171321');ctx.fillStyle=floor;ctx.fillRect(0,ground,W,H-ground);ctx.strokeStyle='#b49bcd22';ctx.lineWidth=1;for(let i=0;i<12;i++){let x=i*100;ctx.beginPath();ctx.moveTo(480,ground);ctx.lineTo(x,H);ctx.stroke()}for(let j=1;j<5;j++){let y=ground+j*j*5;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.fillStyle='#d5a856';ctx.fillRect(0,ground,W,2);
 // stage light panels
 for(let i=0;i<6;i++){ctx.fillStyle=i%2?'#f8cb6a':'#f18bb1';ctx.globalAlpha=.7;ctx.fillRect(75+i*148,206,44,3);ctx.globalAlpha=1;}
 if(flash>0){ctx.fillStyle=`rgba(255,255,255,${flash*.55})`;ctx.fillRect(0,0,W,H)} }
function drawHud(){const [a,b]=fightersLive;drawHealth(44,40,360,22,a,'left');drawHealth(556,40,360,22,b,'right');ctx.textAlign='center';ctx.fillStyle='#fff';ctx.font='900 30px "Barlow Condensed",sans-serif';ctx.fillText(String(timer).padStart(2,'0'),480,60);ctx.fillStyle='#ffc95e';ctx.font='700 8px "DM Mono",monospace';ctx.fillText(`ROUND ${round}`,480,26);ctx.fillStyle='#ffffffaa';ctx.font='700 9px "DM Mono",monospace';ctx.fillText('VS',480,83);}
function drawHealth(x,y,w,h,f,side){ctx.fillStyle='#0c0b15';ctx.fillRect(x-3,y-3,w+6,h+6);ctx.fillStyle='#2e293b';ctx.fillRect(x,y,w,h);let amt=f.health/100;ctx.fillStyle=f.health<28?'#ff5366':fighters[f.kind].color;let fillw=w*amt;if(side==='right')ctx.fillRect(x+w-fillw,y,fillw,h);else ctx.fillRect(x,y,fillw,h);ctx.fillStyle='#fff';ctx.font='800 16px "Barlow Condensed",sans-serif';ctx.textAlign=side==='left'?'left':'right';ctx.fillText(fighters[f.kind].name,x, y-8);ctx.fillStyle='#d0c4dd';ctx.font='8px "DM Mono",monospace';ctx.fillText(f.player===1?(mode===2?'P1 • WASD':'YOU • WASD'):(mode===2?'P2 • ARROWS':'CPU'),side==='left'?x:x+w,y+39);
 // energy meter
 ctx.fillStyle='#171323';ctx.fillRect(x,y+30,w,5);ctx.fillStyle='#ffc95e';let ew=w*f.energy/100;if(side==='right')ctx.fillRect(x+w-ew,y+30,ew,5);else ctx.fillRect(x,y+30,ew,5);ctx.fillStyle='#a89cb8';ctx.textAlign=side==='left'?'left':'right';ctx.font='7px "DM Mono",monospace';ctx.fillText('SIGNATURE',side==='left'?x:x+w,y+45);}
function drawRoundIntro(){ctx.save();ctx.globalAlpha=Math.min(1,(2.1-roundTimer)*2);ctx.textAlign='center';ctx.font='900 42px "Barlow Condensed",sans-serif';ctx.fillStyle='#fff';ctx.shadowColor='#080610';ctx.shadowBlur=14;ctx.fillText(roundTimer<.9?'FIGHT!':'ROUND 1',480,180);ctx.restore();}

function drawFighter(f){const data=fighters[f.kind],x=f.x,y=f.y,dir=f.face,walking=Math.sin(f.walk*2.7),atk=f.attack;ctx.save();ctx.translate(x,y);ctx.scale(dir,1);
 // shadow
 ctx.fillStyle='#08071088';ctx.beginPath();ctx.ellipse(0,0,42,9,0,0,Math.PI*2);ctx.fill();
 let bob=f.jumping?0:Math.abs(walking)*2;ctx.translate(0,-bob);
 // rear leg, shoes
 let legSwing=(!atk?walking*6:0);ctx.fillStyle='#17131d';roundRect(-20+legSwing,-48,17,48,5);roundRect(5-legSwing,-47,18,47,5);ctx.fillStyle=data.accent;roundRect(-24+legSwing,-7,26,8,3);roundRect(0-legSwing,-7,28,8,3);
 // pants
 ctx.fillStyle=f.kind===0?'#19151c':'#d7d3d4';roundRect(-22,-86,43,42,6);if(f.kind===1){ctx.fillStyle='#7b2032';ctx.fillRect(-21,-83,41,5);ctx.fillStyle='#deb751';ctx.fillRect(-1,-87,4,43)}else{ctx.fillStyle=data.accent;ctx.fillRect(-21,-49,41,4)}
 // torso
 ctx.fillStyle=f.flash>0?'#fff':data.color;roundRect(-23,-139,46,57,9);ctx.fillStyle='#ffffff22';ctx.fillRect(-15,-136,7,48);
 if(f.kind===0){ // iconic red jacket details
 ctx.fillStyle='#22202a';ctx.beginPath();ctx.moveTo(-2,-136);ctx.lineTo(3,-127);ctx.lineTo(-1,-116);ctx.lineTo(4,-104);ctx.lineTo(0,-83);ctx.lineTo(-7,-84);ctx.lineTo(-5,-106);ctx.lineTo(-9,-117);ctx.closePath();ctx.fill();ctx.fillStyle=data.accent;for(let i=0;i<5;i++)ctx.fillRect(12,-127+i*8,6,3);ctx.fillStyle='#f6d85b';ctx.fillRect(-20,-102,6,16);}
 else{ // jersey #23
 ctx.fillStyle='#fff4';ctx.fillRect(-17,-125,34,2);ctx.fillStyle='#fff';ctx.font='900 16px "Barlow Condensed",sans-serif';ctx.textAlign='center';ctx.fillText('23',0,-101);ctx.fillStyle=data.accent;ctx.fillRect(-22,-84,44,5);}
 // neck/head
 ctx.fillStyle=data.skin;roundRect(-8,-151,16,15,4);ctx.fillStyle=f.flash>0?'#fff':data.skin;ctx.beginPath();ctx.ellipse(0,-165,16,19,0,0,Math.PI*2);ctx.fill();
 // hair silhouette
 ctx.fillStyle=data.hair;if(f.kind===0){ctx.beginPath();ctx.ellipse(0,-175,18,12,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillRect(-17,-177,5,16);ctx.fillRect(12,-177,5,18);}else{ctx.beginPath();ctx.arc(0,-170,16,Math.PI,Math.PI*2);ctx.fill();ctx.fillRect(-15,-171,30,4);}
 // face
 ctx.fillStyle='#21161b';ctx.fillRect(5,-168,3,2);ctx.fillRect(10,-168,3,2);ctx.strokeStyle='#4b2725';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(6,-158);ctx.lineTo(12,-158);ctx.stroke();
 // arms and attack poses
 let armY=-124,armX=dir?1:1,armAngle=0;if(atk&&atk.t>=atk.startup-3&&atk.t<atk.startup+atk.active){armAngle=-.8;armX=19;}else if(f.block){armAngle=-.75;armX=7;}else armX=walking*2;
 ctx.save();ctx.translate(17,-127);ctx.rotate(armAngle);ctx.fillStyle=data.skin;roundRect(-1,0,12,31,5);ctx.fillStyle=data.color;roundRect(-3,-2,14,10,4);ctx.fillStyle=data.skin;ctx.beginPath();ctx.arc(5,31,7,0,Math.PI*2);ctx.fill();ctx.restore();
 ctx.save();ctx.translate(-18,-127);ctx.rotate(f.block?.65:(!atk?-.12:0));ctx.fillStyle=data.color;roundRect(-2,0,13,11,4);ctx.fillStyle=data.skin;roundRect(0,8,11,26,5);ctx.beginPath();ctx.arc(6,34,7,0,Math.PI*2);ctx.fill();ctx.restore();
 // signature glimmer / blocking guard
 if(atk&&atk.type==='special'){ctx.globalAlpha=.6;ctx.strokeStyle=data.accent;ctx.lineWidth=5;ctx.beginPath();ctx.arc(25,-105,39,-1.2,.9);ctx.stroke();ctx.globalAlpha=1}
 if(f.block){ctx.strokeStyle='#8feaffaa';ctx.lineWidth=3;ctx.beginPath();ctx.arc(5,-108,47,-1.1,1.1);ctx.stroke()}
 ctx.restore();}
function roundRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
function drawEffects(){for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/.75);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;for(const t of texts){ctx.globalAlpha=Math.min(1,t.life*2);ctx.fillStyle=t.color;ctx.textAlign='center';ctx.font='900 22px "Barlow Condensed",sans-serif';ctx.shadowColor='#080610';ctx.shadowBlur=8;ctx.fillText(t.text,t.x,t.y);ctx.shadowBlur=0}ctx.globalAlpha=1;}
function drawMenu(){ctx.fillStyle='#08071077';ctx.fillRect(0,0,W,H);ctx.textAlign='center';ctx.fillStyle='#ffc95e';ctx.font='700 11px "DM Mono",monospace';ctx.letterSpacing='4px';ctx.fillText('THE SHOWDOWN STARTS HERE',480,91);ctx.letterSpacing='0px';ctx.fillStyle='#fff';ctx.font='900 70px "Barlow Condensed",sans-serif';ctx.shadowColor='#130e20';ctx.shadowBlur=20;ctx.fillText('LEGENDS',480,160);ctx.shadowBlur=0;ctx.fillStyle='#d5ccdf';ctx.font='600 12px "DM Mono",monospace';ctx.fillText('ICON CLASH',480,183);
 // character cards
 const cardW=266,cardY=224;fighters.forEach((f,i)=>{let cx=i===0?321:639;let chosen=selected===i;ctx.fillStyle=chosen?'#29203a':'#171424';ctx.strokeStyle=chosen?f.accent:'#655875';ctx.lineWidth=chosen?2:1;ctx.beginPath();ctx.roundRect(cx-cardW/2,cardY,cardW,115,8);ctx.fill();ctx.stroke();ctx.fillStyle=f.color;ctx.fillRect(cx-cardW/2,cardY,4,115);ctx.fillStyle=f.accent;ctx.font='700 8px "DM Mono",monospace';ctx.fillText(i===selected?'★ YOUR FIGHTER':'ICON',cx,cardY+20);ctx.fillStyle='#fff';ctx.font='900 25px "Barlow Condensed",sans-serif';ctx.fillText(f.name,cx,cardY+56);ctx.fillStyle='#b9b0c6';ctx.font='9px "DM Mono",monospace';ctx.fillText(f.tag,cx,cardY+78);ctx.fillStyle=f.accent;ctx.font='700 9px "DM Mono",monospace';ctx.fillText(f.special,cx,cardY+99);});
