function cpuInput(f,other,dt){const d=other.x-f.x,dist=Math.abs(d);f.face=d>=0?1:-1;f.aiClock-=dt;const q={left:false,right:false,jump:false,block:false,light:false,heavy:false,special:false};if(mode===2)return input(2);if(dist>112){if(d>0)q.right=true;else q.left=true;if(dist>230&&Math.random()<.008)q.jump=true;}else{if(other.attack&&Math.random()<.07)q.block=true;if(f.aiClock<=0){f.aiClock=.34+Math.random()*.55;let r=Math.random();if(f.energy>=45&&dist<190&&r<.2)q.special=true;else if(r<.55)q.light=true;else if(r<.84)q.heavy=true;else q.block=true;}else if(f.aiClock>.16&&f.attackCooldown===0&&Math.random()<.035)q.light=true;}return q;}
function initiateAttack(f,type){if(f.attackCooldown>0||f.stun>0||f.attack)return;let spec={light:{startup:7,active:7,recovery:17,damage:7,range:82,cost:0},heavy:{startup:15,active:9,recovery:25,damage:13,range:102,cost:0},special:{startup:18,active:12,recovery:35,damage:19,range:185,cost:45}}[type];if(type==='special'&&f.energy<spec.cost)return;if(type==='special')f.energy-=spec.cost;f.attack={type,t:0,...spec,hit:false};f.attackCooldown=spec.startup+spec.active+spec.recovery;f.hitOnce=false;sound(type==='special'?580:type==='heavy'?340:230,.07);}
