 if(!f.attack&&f.stun<=0){let dir=(q.right?1:0)-(q.left?1:0);if(!f.block){f.vx=dir*235;if(dir)f.walk+=dt*9;else f.walk*=.75;}else f.vx*=.7;if(q.jump&&f.y>=ground-1){f.vy=-480;f.jumping=true;sound(300,.06)}if(q.light)initiateAttack(f,'light');else if(q.heavy)initiateAttack(f,'heavy');else if(q.special)initiateAttack(f,'special');}
 if(f.attack){f.attack.t+=dt*60;if(f.attack.t>=f.attack.startup&&f.attack.t<f.attack.startup+f.attack.active&&!f.attack.hit){let reach=f.attack.range;const close=Math.abs(other.x-f.x)<reach+23,front=(other.x-f.x)*f.face>0;if(close&&front&&Math.abs(other.y-f.y)<92){let blocked=other.block&&other.face===-f.face;let dmg=blocked?Math.ceil(f.attack.damage*.18):f.attack.damage;other.health=Math.max(0,other.health-dmg);other.energy=Math.min(100,other.energy+(blocked?7:13));f.energy=Math.min(100,f.energy+10);other.stun=blocked?5:(f.attack.type==='heavy'?15:10);other.vx=blocked?f.face*70:f.face*(f.attack.type==='special'?320:210);other.flash=8;f.attack.hit=true;f.hitOnce=true;shake=blocked?4:9;flash=blocked?.08:.16;burst(other.x,other.y-60,blocked?'#ffc95e':fighters[f.kind].accent,blocked?8:17);floatingText(other.x,other.y-114,blocked?'GUARD!':`-${dmg}`,blocked?'#ffe39a':'#fff');sound(blocked?180:f.attack.type==='special'?120:90,.11);}}if(f.attack.t>=f.attack.startup+f.attack.active+f.attack.recovery)f.attack=null;}
 f.vy+=1250*dt;f.y+=f.vy*dt;if(f.y>=ground){f.y=ground;f.vy=0;f.jumping=false;}f.x+=f.vx*dt;f.x=Math.max(70,Math.min(W-70,f.x));if(!f.attack&&f.stun<=0)f.vx*=Math.pow(.001,dt);}
