 let armAngle=0;if(atk&&atk.t>=atk.startup-3&&atk.t<atk.startup+atk.active)armAngle=-.8;else if(f.block)armAngle=-.75;ctx.save();ctx.translate(17,-127);ctx.rotate(armAngle);ctx.fillStyle=data.skin;roundRect(-1,0,12,31,5);ctx.fillStyle=data.color;roundRect(-3,-2,14,10,4);ctx.fillStyle=data.skin;ctx.beginPath();ctx.arc(5,31,7,0,Math.PI*2);ctx.fill();ctx.restore();ctx.save();ctx.translate(-18,-127);ctx.rotate(f.block?.65:(!atk?-.12:0));ctx.fillStyle=data.color;roundRect(-2,0,13,11,4);ctx.fillStyle=data.skin;roundRect(0,8,11,26,5);ctx.beginPath();ctx.arc(6,34,7,0,Math.PI*2);ctx.fill();ctx.restore();if(atk&&atk.type==='special'){ctx.globalAlpha=.6;ctx.strokeStyle=data.accent;ctx.lineWidth=5;ctx.beginPath();ctx.arc(25,-105,39,-1.2,.9);ctx.stroke();ctx.globalAlpha=1}if(f.block){ctx.strokeStyle='#8feaffaa';ctx.lineWidth=3;ctx.beginPath();ctx.arc(5,-108,47,-1.1,1.1);ctx.stroke()}ctx.restore();}
