(()=>{'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),W=960,H=540,G=438;
const chars=[{name:'MICHAEL JACKSON',color:'#e94155',accent:'#f2c955',skin:'#9a684f',special:'MOONWALKER RUSH'},{name:'LEBRON JAMES',color:'#6e4ee7',accent:'#ffc84f',skin:'#8e5c40',special:'CROWN BREAKER'}];
let selected=0,mode=1,state='menu',paused=false,timer=60,roundTime=0,last=0,shake=0,flash=0,soundOn=true,audio;
const keys=new Set(),touch=new Set(),sparks=[],labels=[];let fighters=[];
const map={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down'};
function make(kind,x,player){return{kind,x,y:G,vx:0,vy:0,face:player===1?1:-1,hp:100,player,attack:null,cool:0,stun:0,block:false,jump:false,walk:0,energy:0,ai:0,glow:0}}
function start(){fighters=[make(selected,260,1),make(1-selected,700,2)];timer=60;roundTime=0;state='fight';paused=false;sparks.length=0;labels.length=0}
function beep(f=240,d=.08){if(!soundOn)return;try{audio||=new(window.AudioContext||window.webkitAudioContext)();let o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch{}}
function down(k){return keys.has(k)||touch.has(k)}
function input(p){return p===1?{left:down('a'),right:down('d'),up:down('w'),block:down('s'),light:down('f'),heavy:down('g'),special:down('h')}:{left:down('left'),right:down('right'),up:down('up'),block:down('down'),light:down('j'),heavy:down('k'),special:down('l')}}
function cpu(f,o,dt){let d=o.x-f.x,dist=Math.abs(d);f.face=d>=0?1:-1;f.ai-=dt;let q={left:false,right:false,up:false,block:false,light:false,heavy:false,special:false};if(mode===2)return input(2);if(dist>105){q[d>0?'right':'left']=true}else if(f.ai<=0){f.ai=.35+Math.random()*.5;let r=Math.random();if(f.energy>=45&&r<.2)q.special=true;else if(r<.55)q.light=true;else if(r<.82)q.heavy=true;else q.block=true;}return q}
function begin(f,type){if(f.cool>0||f.stun>0||f.attack)return;let a={light:[7,7,17,7,82,0],heavy:[15,9,25,13,102,0],special:[18,12,35,19,185,45]}[type];if(type==='special'&&f.energy<a[5])return;if(type==='special')f.energy-=a[5];f.attack={type,t:0,start:a[0],active:a[1],recovery:a[2],damage:a[3],range:a[4],hit:false};f.cool=a[0]+a[1]+a[2];beep(type==='special'?580:type==='heavy'?340:230)}

function updateFighter(f,q,o,dt){f.block=q.block&&f.y>=G-1&&!f.attack;f.cool=Math.max(0,f.cool-dt*60);f.stun=Math.max(0,f.stun-dt*60);f.glow=Math.max(0,f.glow-dt*60);if(!f.attack&&f.stun<=0){let dir=(q.right?1:0)-(q.left?1:0);if(!f.block){f.vx=dir*235;if(dir)f.walk+=dt*9;else f.walk*=.75}else f.vx*=.7;if(q.up&&f.y>=G-1){f.vy=-480;f.jump=true;beep(300,.06)}if(q.light)begin(f,'light');else if(q.heavy)begin(f,'heavy');else if(q.special)begin(f,'special')}
if(f.attack){let a=f.attack;a.t+=dt*60;if(a.t>=a.start&&a.t<a.start+a.active&&!a.hit&&Math.abs(o.x-f.x)<a.range+23&&(o.x-f.x)*f.face>0&&Math.abs(o.y-f.y)<92){let blocked=o.block&&o.face===-f.face,dmg=blocked?Math.ceil(a.damage*.18):a.damage;o.hp=Math.max(0,o.hp-dmg);o.energy=Math.min(100,o.energy+(blocked?7:13));f.energy=Math.min(100,f.energy+10);o.stun=blocked?5:a.type==='heavy'?15:10;o.vx=f.face*(blocked?70:a.type==='special'?320:210);o.glow=8;a.hit=true;shake=blocked?4:9;flash=blocked?.08:.16;burst(o.x,o.y-60,blocked?'#ffc95e':chars[f.kind].accent,blocked?8:17);labels.push({x:o.x,y:o.y-114,text:blocked?'GUARD!':`-${dmg}`,life:.7,color:blocked?'#ffe39a':'#fff'});beep(blocked?180:a.type==='special'?120:90,.11)}if(a.t>=a.start+a.active+a.recovery)f.attack=null}
f.vy+=1250*dt;f.y+=f.vy*dt;if(f.y>=G){f.y=G;f.vy=0;f.jump=false}f.x=Math.max(70,Math.min(W-70,f.x+f.vx*dt));if(!f.attack&&f.stun<=0)f.vx*=Math.pow(.001,dt)}
function burst(x,y,color,n){for(let i=0;i<n;i++){let a=Math.random()*6.28,s=70+Math.random()*260;sparks.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+Math.random()*.5,color,r:2+Math.random()*4})}}
function finish(){if(state!=='fight')return;state='over';window.winner=fighters[0].hp===fighters[1].hp?'DRAW':fighters[0].hp>fighters[1].hp?'P1':'P2';beep(440,.22)}
function step(dt){if(state==='fight'&&!paused){roundTime+=dt;timer=Math.max(0,60-Math.floor(roundTime));let[a,b]=fighters;a.face=b.x>=a.x?1:-1;b.face=a.x>=b.x?1:-1;updateFighter(a,input(1),b,dt);updateFighter(b,cpu(b,a,dt),a,dt);if(Math.abs(a.x-b.x)<53){let p=(53-Math.abs(a.x-b.x))/2;a.x-=Math.sign(b.x-a.x)*p;b.x+=Math.sign(b.x-a.x)*p}if(a.hp<=0||b.hp<=0||!timer)finish()}for(let i=sparks.length-1;i>=0;i--){let p=sparks[i];p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=420*dt;if(p.life<=0)sparks.splice(i,1)}for(let i=labels.length-1;i>=0;i--){labels[i].life-=dt;labels[i].y-=36*dt;if(labels[i].life<=0)labels.splice(i,1)}shake=Math.max(0,shake-dt*30);flash=Math.max(0,flash-dt)}
function rect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}

