function hud(){let[a,b]=fighters;health(44,40,360,22,a,false);health(556,40,360,22,b,true);ctx.textAlign='center';ctx.fillStyle='#fff';ctx.font='900 30px sans-serif';ctx.fillText(String(timer).padStart(2,'0'),480,60);ctx.fillStyle='#ffc95e';ctx.font='700 8px monospace';ctx.fillText('ROUND 1',480,26);ctx.fillStyle='#ffffffaa';ctx.fillText('VS',480,83)}
function health(x,y,w,h,f,right){ctx.fillStyle='#0c0b15';ctx.fillRect(x-3,y-3,w+6,h+6);ctx.fillStyle='#2e293b';ctx.fillRect(x,y,w,h);let fw=w*f.hp/100;ctx.fillStyle=f.hp<28?'#ff5366':chars[f.kind].color;ctx.fillRect(right?x+w-fw:x,y,fw,h);ctx.fillStyle='#fff';ctx.textAlign=right?'right':'left';ctx.font='800 16px sans-serif';ctx.fillText(chars[f.kind].name,right?x+w:x,y-8);ctx.fillStyle='#d0c4dd';ctx.font='8px monospace';ctx.fillText(f.player===1?(mode===2?'P1 • WASD':'YOU • WASD'):(mode===2?'P2 • ARROWS':'CPU'),right?x+w:x,y+39);ctx.fillStyle='#171323';ctx.fillRect(x,y+30,w,5);ctx.fillStyle='#ffc95e';let ew=w*f.energy/100;ctx.fillRect(right?x+w-ew:x,y+30,ew,5);ctx.fillStyle='#a89cb8';ctx.font='7px monospace';ctx.fillText('SIGNATURE',right?x+w:x,y+45)}

